	zip.Describe("github.com/hanzoai/cloud/apps/commerce POST /billing/gateway/read", zip.Doc{
		Description: "Reads one USDC top-up back. A payment belonging to another payer answers as\na MISS, exactly as an id that names nothing.\n\nA named handler, not a closure, so zipdoc can lift this prose into the registry.",
	})
	zip.Describe("github.com/hanzoai/cloud/apps/commerce POST /billing/gateway/submit", zip.Doc{
		Description: "Takes one payer's signed USDC payment to the treasury, and answers what\nbecame of it.\n\naccepted means Circle Gateway LOCKED the payer's USDC and the payer is\ncredited (or, past the unconfirmed-credit cap, will be when Gateway confirms\nit); pending means the outcome is not known yet and resolves on its own; a\nrefusal carries Gateway's reason. Presenting the same payment again is the\nsame payment.\n\nA named handler, not a closure, so zipdoc can lift this prose into the registry.",
	})
	zip.Describe("github.com/hanzoai/cloud/apps/commerce POST /billing/gateway/terms", zip.Doc{
		Description: "Answers the terms a payer signs a USDC top-up against: the treasury to pay,\nthe networks and USDC contracts, the EIP-712 domain and types, the limits,\nand a nonce issued to this payer and no other.\n\nThe payer is resolved by the endpoint and arrives here as a value; the nonce\nbinds it, so a payment signed against these terms cannot be presented by\nanyone else.\n\nA named handler, not a closure, so zipdoc can lift this prose into the registry.",
	})
	zip.Describe("github.com/hanzoai/cloud/apps/commerce POST /billing/invoice/collect", zip.Doc{
		Description: "Collects an issued invoice: credit grants first, then prepaid balance, then the\ncard on file — the same waterfall the dunning workflow runs.\n\nA DECLINE IS NOT AN ERROR. It answers with paid=false, a reason, and the\ninvoice still open, because a declined collection is a normal business outcome\nthat must remain retryable — and because sealing it as a failure would wedge\ndunning behind a replayed decline. Only a successful collection is sealed, so a\nretry of a paid invoice replays the receipt instead of charging again.\n\nA named handler, not a closure, so zipdoc can lift this prose into the registry.",
		Fields: map[string]string{
			"Collected.balanceUsedCents":   "BalanceUsedCents is how much was covered by prepaid balance.",
			"Collected.cardChargedCents":   "CardChargedCents is how much was charged to the card on file.",
			"Collected.creditUsedCents":    "CreditUsedCents is how much was covered by credit grants.",
			"Collected.invoice":            "Invoice is the invoice AFTER the attempt — its status is the authority on\nwhat happened, not this struct's other fields.",
			"Collected.paid":               "Paid reports whether the invoice is now settled in full. A false here with\nno error is a DECLINE: the invoice stays open and may be collected again.",
			"Collected.processorRef":       "ProcessorRef is the processor's reference for any card charge — the field\nthat proves money moved at the gateway rather than only in our ledger.",
			"Collected.reason":             "Reason explains a decline or partial collection. Empty on success.",
			"Invoice.amountDueCents":       "AmountDueCents is what remains collectible.",
			"Invoice.amountPaidCents":      "AmountPaidCents is what has been collected so far.",
			"Invoice.createdAt":            "CreatedAt is when the draft was raised, RFC3339.",
			"Invoice.currency":             "Currency is the ISO 4217 code.",
			"Invoice.customerEmail":        "CustomerEmail is where it is sent.",
			"Invoice.id":                   "ID is the invoice id — what the issue, collect and void ops address.",
			"Invoice.lines":                "Lines are the charges on the invoice.",
			"Invoice.number":               "Number is the human-facing invoice number, e.g. \"INV-0042\". A draft has\nnone; issuing assigns it.",
			"Invoice.paymentRef":           "PaymentRef is the processor reference for the collection, once paid.",
			"Invoice.quote":                "Quote is the invoice's price in the buyer's own currency: the bound quote once\npaid, else the quote an awaiting-bank attempt is bound to, else the displayed\nprice of what is due. Absent in the plan's currency.",
			"Invoice.status":               "Status is draft, open, paid, void or uncollectible. A draft is not\ncollectible; issuing moves it to open.",
			"Invoice.subtotalCents":        "SubtotalCents is the sum of the lines.",
			"Invoice.userId":               "UserID is the customer billed.",
			"InvoiceLine.amount":           "Amount is the line total in whole cents (250000 is $2,500.00).",
			"InvoiceLine.description":      "Description is the human-readable line, e.g. \"Advisory retainer — August\".",
			"InvoiceLine.quantity":         "Quantity is the number of units, when the line is metered. Optional.",
			"InvoiceLine.unitPrice":        "UnitPrice is the per-unit price in cents, when the line is metered. Optional.",
			"InvoiceRef.brand":             "Brand is the brand that bills (hanzo, lux, zoo, pars), whose mark and\naddress a rendered invoice carries. The edge sets it from the caller's\nissuer; empty is Hanzo.",
			"InvoiceRef.id":                "ID is the invoice id.",
			"PriceQuote.amount":            "Amount is the price in the currency's minor unit; render Amount/10^Decimals.",
			"PriceQuote.baseRate":          "BaseRate is the processor's rate before its fee and premium.",
			"PriceQuote.currency":          "Currency is the lower-case ISO 4217 code the buyer pays in.",
			"PriceQuote.decimals":          "Decimals is how many digits the minor unit is past the point.",
			"PriceQuote.disclosure":        "Disclosure is the sentence the buyer is shown with the price.",
			"PriceQuote.exchangeRate":      "ExchangeRate is the processor's effective rate, when the quote is the processor's.",
			"PriceQuote.feeRate":           "FeeRate is the processor's conversion fee, as a fraction.",
			"PriceQuote.fxFee":             "FXFee says who bears the conversion cost: pass (in the rate) or absorb.",
			"PriceQuote.increment":         "Increment is the minor-unit step the amount was rounded up to.",
			"PriceQuote.lockExpiresAt":     "LockExpiresAt is when the processor's lock lapses, in unix seconds.",
			"PriceQuote.premium":           "Premium is the processor's lock premium, as a fraction.",
			"PriceQuote.quoteId":           "QuoteID is the processor's locked quote the payment is bound to; absent for a\nprice shown and not yet bound.",
			"PriceQuote.rate":              "Rate is the rate the amount was made at, per major unit.",
			"PriceQuote.referenceProvider": "ReferenceProvider names the source of ReferenceRate.",
			"PriceQuote.referenceRate":     "ReferenceRate is the market reference the processor's rate was measured against.",
			"PriceQuote.source":            "Source is where Rate came from: processor, reference or none.",
			"PriceQuote.usdCents":          "UsdCents is the credit the payment buys, exactly.",
		},
	})
