	zip.Describe("github.com/hanzoai/cloud/apps/commerce POST /billing/subscription/token", zip.Doc{
		Description: "Replaces the token a subscription renews on with a fresh one that covers the next\nrenewal, before the renewal is attempted, and answers what is left on it. A token that\ndoes not cover the renewal is declined with a code, and the subscription keeps the one it had.\n\nA named handler, not a closure, so zipdoc can lift this prose into the registry.",
		Fields: map[string]string{
			"AgentError.code":             "Code is the refusal, such as token_over_limit or authentication_required.",
			"AgentError.message":          "Message says why.",
			"TokenRoom.covers":            "Covers says the token covers the next renewal.",
			"TokenRoom.expiresAt":         "ExpiresAt is when the token expires.",
			"TokenRoom.maxCents":          "MaxCents is the most the token may be charged in all.",
			"TokenRoom.recurringInterval": "RecurringInterval is the interval the token may renew on.",
			"TokenRoom.remainingCents":    "RemainingCents is what the token can still be charged.",
			"TokenRoom.renewalCents":      "RenewalCents is what the next renewal charges.",
			"TokenSupplied.error":         "Error is why the token was declined.",
			"TokenSupplied.status":        "Status is ok or declined.",
			"TokenSupplied.token":         "Token is what is left on the token now.",
		},
	})
